create table public.blog_avaliacoes (id uuid primary key default gen_random_uuid(),post_id uuid not null references public.blog_posts(id) on delete cascade,sessao_id uuid not null,nota smallint not null check(nota between 1 and 5),criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now(),unique(post_id,sessao_id));
create table public.blog_comentarios (id uuid primary key default gen_random_uuid(),post_id uuid not null references public.blog_posts(id) on delete cascade,sessao_id uuid not null,nome text check(char_length(nome)<=80),comentario text not null check(char_length(comentario) between 10 and 1200),status text not null default 'pendente' check(status in ('pendente','aprovado','rejeitado')),criado_em timestamptz not null default now());
create index blog_avaliacoes_post_id_idx on public.blog_avaliacoes(post_id);
create index blog_comentarios_post_id_idx on public.blog_comentarios(post_id);
alter table public.blog_avaliacoes enable row level security; alter table public.blog_comentarios enable row level security;
create policy blog_avaliacoes_admin on public.blog_avaliacoes for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy blog_comentarios_admin on public.blog_comentarios for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
revoke all on public.blog_avaliacoes,public.blog_comentarios from anon; grant select,update,delete on public.blog_avaliacoes,public.blog_comentarios to authenticated;
create function public.registrar_avaliacao_blog(p_post_id uuid,p_sessao_id uuid,p_nota smallint) returns void language plpgsql security definer set search_path='' as $$ begin if p_nota not between 1 and 5 or not exists(select 1 from public.blog_posts where id=p_post_id and status='publicado') then raise exception 'Avaliação inválida'; end if; insert into public.blog_avaliacoes(post_id,sessao_id,nota) values(p_post_id,p_sessao_id,p_nota) on conflict(post_id,sessao_id) do update set nota=excluded.nota,atualizado_em=now(); end $$;
create function public.enviar_comentario_blog(p_post_id uuid,p_sessao_id uuid,p_nome text,p_comentario text) returns void language plpgsql security definer set search_path='' as $$ begin if char_length(trim(p_comentario)) not between 10 and 1200 or not exists(select 1 from public.blog_posts where id=p_post_id and status='publicado') then raise exception 'Comentário inválido'; end if; if (select count(*) from public.blog_comentarios where post_id=p_post_id and sessao_id=p_sessao_id and criado_em>now()-interval '1 day')>=3 then raise exception 'Limite diário atingido'; end if; insert into public.blog_comentarios(post_id,sessao_id,nome,comentario) values(p_post_id,p_sessao_id,nullif(left(trim(p_nome),80),''),trim(p_comentario)); end $$;
revoke all on function public.registrar_avaliacao_blog(uuid,uuid,smallint),public.enviar_comentario_blog(uuid,uuid,text,text) from public;
grant execute on function public.registrar_avaliacao_blog(uuid,uuid,smallint),public.enviar_comentario_blog(uuid,uuid,text,text) to anon,authenticated;
